action_details.action_postfix:
result.total_interest_income 0 max
/result.pa_taxable_interest xdef

result.pa_taxable_interest 0 gt
{
  "PA Class 2 Interest: $" result.pa_taxable_interest cvs strconcat job.audit_trail swap addto
} if

