{
  result.total_social_security /result.pa_social_security_exclusion xdef
  "PA Social Security exclusion (100%): $" result.pa_social_security_exclusion cvs strconcat job.audit_trail swap addto
} if




"PA excludes all retirement income: Social Security, pensions, IRA, military retirement" job.audit_trail swap addto
